/* =========================================================
   문법 문제 파일 (여기만 고치면 됩니다)

   어휘 문제는 questions.js, 문법 문제는 이 파일입니다.
   =========================================================

   ▶ 회차 하나는 이렇게 생겼습니다.

     {
       title: "01회 맞춤법 1",            // 회차 고르기 화면에 보일 이름
       group: "고등부",                   // 이 회차를 볼 반 (고등부 / 중등부)
       subtitle: "헷갈리는 맞춤말 20개",  // 그 아래 작게 보일 설명 (없으면 "" )
       questions: [
         ... 문제들 ...
       ]
     },


   ▶ 문제는 세 가지 모양으로 낼 수 있습니다.


   ① 둘 중 하나 고르기 (맞춤법)

     {
       ask: "맞춤법이 바른 것은?",        // 물음 (작은 글씨로 위에 나옵니다)
       sentence: "그릇을 ○○했다.",       // 제시문 (큰 글씨. 없으면 이 줄을 빼세요)
       choices: ["설거지", "설겆이"],
       answer: 1,                        // 정답이 몇 번째 보기인지
       explanation: "'설겆다' 라는 말이 없어졌으므로 '설거지' 로 적습니다."
     },

     제시문 없이 낱말 둘만 보여 주고 싶으면 sentence 줄을 빼면 됩니다.

     {
       ask: "맞춤법에 맞는 것은?",
       choices: ["싹싹", "싹삭"],
       answer: 1,
       explanation: "'싹싹'이 바릅니다. 같은 음절이 겹쳐 나므로 된소리로 적습니다."
     },

     보기 순서는 앱이 섞으니 바른 말을 먼저 적어도 됩니다.


   ② OX 문제

     ox: true 라고 적으면 보기를 O·X 로 앱이 알아서 넣습니다.
     answer 는 맞으면 1, 틀리면 2 입니다.

     {
       ask: "다음 설명이 맞으면 O, 틀리면 X",
       sentence: "'몇일' 은 바른 표기이다.",
       ox: true,
       answer: 2,
       explanation: "'며칠' 이 바른 표기입니다. '몇일' 은 없는 말입니다."
     },


   ③ 5지선다 (보기를 다섯 개까지 넣을 수 있습니다)

     {
       ask: "다음 중 띄어쓰기가 옳은 것은?",
       choices: [
         "할 수 밖에 없다",
         "할 수밖에 없다",
         "할수 밖에 없다",
         "할수밖에 없다",
         "할 수 밖에없다"
       ],
       answer: 2,
       explanation: "'수밖에' 는 붙여 씁니다."
     },

     보기 순서는 학생마다 섞여서 나옵니다.
     해설에 '①은 …, ③은 …' 처럼 보기 번호를 적었다면 순서가 바뀌면 안 되므로
     문제에 keepOrder: true 를 적어 주세요. 그러면 적은 순서 그대로 나옵니다.


   ▶ 원본의 밑줄은 괄호로 적습니다

     앱은 밑줄을 그릴 수 없어서, 기출 문제에서 밑줄 친 말은 ( ) 로 묶었습니다.
     물음도 '밑줄 친' 이 아니라 '괄호 친' 이라고 적습니다. (11회·12회 문장 성분)


   ▶ 한 회차 안에서 문제 이름이 겹칠 때

     선생님 화면의 '문제별 정답률' 은 제시문(없으면 정답)으로 문제를 구분합니다.
     한 회차 안에 그 이름이 같은 문제가 둘 있으면 한 칸을 나눠 쓰게 됩니다.
     그럴 때만 name 을 적어 이름을 따로 지어 주세요. name 은 화면에 보이지 않습니다.

       {
         name: "첫눈 (소리의 길이 고르기)",   ← 통계에서 쓸 이름
         ask: "다음 중 소리의 길이가 나머지와 다른 것은?",
         choices: ["눈보라", "말씨", "밤나무", "첫눈", "멀리"],
         answer: 4,
         explanation: "..."
       },


   ▶ 같은 갈래가 너무 많이 나오지 않게 하기

     비슷한 문제가 한 시험에 몰리면 시험이 지루해집니다.
     문제에 갈래 이름(kind)을 적어 두고, 회차에 limit 으로 개수를 정하면
     그 갈래는 한 시험에 그 개수까지만 나옵니다.

       limit: { 동사형용사: 5 },   ← 회차에 적습니다

       {
         kind: "동사형용사",       ← 문제마다 적습니다
         ask: "다음 말은 동사입니까, 형용사입니까?",
         sentence: "늙다",
         choices: ["동사", "형용사"],
         answer: 1,
         explanation: "'늙는다'가 되므로 동사입니다."
       },

     갈래 이름은 아무렇게나 지어도 됩니다. 적지 않은 문제는 개수를 세지 않습니다.
     limit 때문에 문제가 모자라면 앱이 다른 문제로 채우니 문제 수는 줄지 않습니다.

     04~09회는 문제를 갈래끼리 모아 두고, 사이에 회색 제목 줄을 넣어 두었습니다.
     "── 동사·형용사 (동사형용사) · 34문제 ──" 처럼 생겼고, 괄호 안이 갈래 이름(kind)입니다.
     문제를 새로 넣을 때는 같은 갈래의 제목 줄 아래에 넣고,
     문제 안에도 kind 를 똑같이 적어 주세요.


   ▶ 한 번 시험에 나올 문제 구성 정하기

     회차에 mix 를 적으면 그 개수만큼 골고루 뽑아 냅니다.

       mix: { 단순: 18, 객관식: 2 },

     · 단순  = OX 문제와 보기가 둘뿐인 문제 (둘 중 고르기 포함)
     · 객관식 = 보기가 셋 이상인 문제 (5지선다 등)
     · 두 수를 더한 값이 한 번 시험에 나올 문제 수입니다. (지금은 20문제)
       ★ 문제 수를 늘리거나 줄이려면 이 두 숫자만 고치면 됩니다.
     · mix 를 적지 않으면 회차 안에서 아무렇게나 15문제를 뽑습니다.


   ▶ 함께 알아두실 것

     · 보기는 2개부터 5개까지 넣을 수 있습니다. (OX 는 적지 않아도 됩니다)
     · 보기 순서는 앱이 섞어서 냅니다. 단 OX 문제는 섞지 않습니다.
     · 어휘처럼 한자를 보이고 싶으면 word 와 hanja 를 쓰면 됩니다.
       (예: word: "관형어", hanja: "冠形語")
     · 한 번 시험에 나올 문제 수는 위의 mix 로 정합니다.
       재시험 기준은 아래 GRAMMAR_RETEST_MAX 로 따로 정합니다.

   ========================================================= */


/* 문법 재시험 기준
   맞힌 개수가 이 숫자 이하이면 결과 화면에서 '재시험을 봐야 한다'고 안내합니다.
   (지금은 20문제 중 13개 이하)
   어휘는 questions.js 의 RETEST_MAX 를 따로 씁니다. */
var GRAMMAR_RETEST_MAX = 13;

/* 문법 앱 이름 (브라우저 탭과 즐겨찾기에 이 이름이 보입니다)
   어휘는 questions.js 의 QUIZ_TITLE 을 따로 씁니다. */
var GRAMMAR_QUIZ_TITLE = "고등 국어 문법 테스트";


